 balance:p?.colorGradingEnabled?[p.temperature*.01,p.tint*.01,0,0]:[0,0,0,0],lift:[...(p?.colorGradingEnabled?p.lift:[0,0,0]),0],gamma:[...(p?.colorGradingEnabled?p.gamma:[1,1,1]),0],gain:[...(p?.colorGradingEnabled?p.gain:[1,1,1]),0],focus:[p?.focusDistance??10,p?.focusRange??5,p?.dofRadius??4,p?.dofEnabled&&!(p.pathTracingEnabled&&p.pathTracingDOF)?p.dofStrength:0],occlusion:[p?.aoRadius??1,p?.aoBias??.02,p?.aoEnabled&&p.aoMode!=='ambient'&&p.aoMode!=='distanceField'?p.aoIntensity:0,p?.antiAliasing==='fxaa'?p.aaStrength:0],lookup:[p?.colorLookup?p.lookupIntensity:0,0,0,0],camera:[camera?.near??.1,camera?.far??1000,camera?.isOrthographicCamera?1:0,Math.abs(camera?.projectionMatrix?.elements?.[5]??2)*.5],exposure:[p?.autoExposureEnabled?(p.autoExposureWeight??1):0,p?.exposureMinEV??-8,p?.exposureMaxEV??8,p?.exposureTarget??.18],adapt:[p?.exposureSpeedUp??3,p?.exposureSpeedDown??1,0,0]
