export const postUniformNames={grade:'hbGrade',filter:'hbFilter',effects:'hbPostEffects',vignette:'hbVignette',vignetteColor:'hbVignetteColor',balance:'hbBalance',lift:'hbLift',gamma:'hbGamma',gain:'hbGain',lens:'hbLens',bokeh:'hbBokeh',focus:'hbFocus',occlusion:'hbOcclusion',lookup:'hbLookup',camera:'hbCamera',exposure:'hbExposure',adapt:'hbAdapt'};
export function lookupSize(texture){const image=texture?.image,n=image?.height;return Number.isInteger(n)&&n>=2&&n<=64&&image.width===n*n?n:0;}
// The same depth/color formulas feed GLSL and native HLSL; effects remain neutral when disabled.
export const screenPostGLSL=`
float hbLinearDepth(float d){return hbCamera.z>.5?mix(hbCamera.x,hbCamera.y,d):hbCamera.x*hbCamera.y/max(.000001,hbCamera.y-d*(hbCamera.y-hbCamera.x));}
float hbLensRadius(float z){if(hbLens.w<.5)return clamp(abs(z-hbFocus.x)/max(hbFocus.y,.001),0.0,1.0)*hbFocus.z;float diameter=hbLens.x*hbLens.x*abs(1.0-hbFocus.x/max(z,.000001))/(hbLens.y*max(.000001,hbFocus.x-hbLens.x));return min(hbFocus.z,diameter/hbLens.z*hbPostSize.y*.5);}
float hbAperture(float a){if(hbBokeh.x<3.0)return 1.0;float halfAngle=3.14159265359/hbBokeh.x,phase=mod(a-hbBokeh.y+halfAngle,halfAngle*2.0)-halfAngle;return mix(cos(halfAngle)/cos(phase),1.0,hbBokeh.z);}
float hbDepthAt(vec2 uv){return hbLinearDepth(texture2D(hbDepth,clamp(uv,0.0,1.0)).r);}
vec3 hbScreenColor(sampler2D image,vec2 uv){
 vec3 c=texture2D(image,uv).rgb;float z=hbDepthAt(uv);
 if(hbFocus.w>0.0){float radius=hbLensRadius(z);vec3 sum=c;float total=1.0;
  for(int i=0;i<32;i++){if(float(i)>=hbBokeh.w)break;float a=float(i)*2.39996323+hbBokeh.y;vec2 at=clamp(uv+vec2(cos(a),sin(a))*sqrt((float(i)+.5)/hbBokeh.w)*hbAperture(a)*radius/hbPostSize,0.0,1.0);float other=hbDepthAt(at),w=other<z-max(.02,z*.01)?0.0:1.0;sum+=texture2D(image,at).rgb*w;total+=w;}c=mix(c,sum/total,hbFocus.w);}
 if(hbOcclusion.z>0.0&&texture2D(hbDepth,uv).r<.99999){float occ=0.0;vec2 delta=vec2(max(1.0,hbOcclusion.x*hbPostSize.y*hbCamera.w/(hbCamera.z>.5?1.0:max(z,.01))))/hbPostSize;
  for(int i=0;i<8;i++){float a=float(i)*.785398163;float other=hbDepthAt(clamp(uv+vec2(cos(a),sin(a))*delta,0.0,1.0));float difference=z-other;occ+=step(hbOcclusion.y,difference)*(1.0-smoothstep(0.0,hbOcclusion.x*2.0,difference));}c*=max(0.0,1.0-occ*.125*hbOcclusion.z);}
 return c;
}
vec3 hbLookupColor(vec3 c){if(hbLookup.x<=0.0||hbLookup.y<2.0)return c;float n=hbLookup.y,b=clamp(c.b,0.0,1.0)*(n-1.0),slice=floor(b);vec2 at=(clamp(c.rg,0.0,1.0)*(n-1.0)+.5)/vec2(n*n,n);vec3 lo=texture2D(hbLookupMap,at+vec2(slice/n,0.0)).rgb,hi=texture2D(hbLookupMap,at+vec2(min(slice+1.0,n-1.0)/n,0.0)).rgb;return mix(c,mix(lo,hi,fract(b)),hbLookup.x);}
vec3 hbGradeColor(vec3 c){c*=exp2(hbGrade.x)*hbFilter.rgb*exp2(vec3(hbBalance.x,-hbBalance.y,-hbBalance.x));c=pow(max(vec3(0),c+hbLift.rgb),1.0/max(hbGamma.rgb,vec3(.1)))*hbGain.rgb;c=max(vec3(0),(c-.18)*hbGrade.y+.18);float y=dot(c,vec3(.2126,.7152,.0722));c=mix(vec3(y),c,hbGrade.z);float a=hbGrade.w;vec3 axis=vec3(.577350269);return max(vec3(0),c*cos(a)+cross(axis,c)*sin(a)+axis*dot(axis,c)*(1.0-cos(a)));}
`;
export const postGLSL=`
uniform vec4 hbGrade,hbFilter,hbPostEffects,hbVignette,hbVignetteColor,hbBalance,hbLift,hbGamma,hbGain,hbLens,hbBokeh,hbFocus,hbOcclusion,hbLookup,hbCamera,hbExposure,hbAdapt;uniform vec2 hbPostSize;uniform sampler2D hbDepth,hbLookupMap,hbExposureMap;
${screenPostGLSL}
vec4 hbPostColor(sampler2D image,vec2 uv){vec2 delta=(uv-.5)*hbPostEffects.z*.015;vec4 c=texture2D(image,uv);c.rgb=hbScreenColor(image,uv);if(hbPostEffects.z>0.0){c.r=hbScreenColor(image,clamp(uv+delta,0.0,1.0)).r;c.b=hbScreenColor(image,clamp(uv-delta,0.0,1.0)).b;}if(hbExposure.x>0.0)c.rgb*=exp2(texture2D(hbExposureMap,vec2(.5)).r*hbExposure.x);c.rgb=hbGradeColor(c.rgb);if(hbPostEffects.x>0.0){vec2 d=(uv-hbVignette.xy)*2.0;d.x*=hbVignette.z>.5?hbPostSize.x/hbPostSize.y:1.0;float f=smoothstep(1.0-max(hbPostEffects.y,.001),1.0,length(d))*hbPostEffects.x;c.rgb=mix(c.rgb,hbVignetteColor.rgb,f);}if(hbPostEffects.w>0.0){float noise=fract(sin(dot(floor(uv*hbPostSize)+floor(hbVignette.w*60.0),vec2(12.9898,78.233)))*43758.5453)-.5;c.rgb=max(vec3(0),c.rgb+noise*hbPostEffects.w*.08);}return c;}`;
export const meterGLSL=`uniform sampler2D hbMeterSource,hbPreviousExposure;uniform vec4 hbExposure,hbAdapt;void main(){float sum=0.0;for(int y=0;y<8;y++)for(int x=0;x<8;x++){vec3 c=texture2D(hbMeterSource,(vec2(float(x),float(y))+.5)/8.0).rgb;sum+=log2(max(.00001,dot(c,vec3(.2126,.7152,.0722))));}float target=clamp(log2(hbExposure.w)-sum/64.0,hbExposure.y,hbExposure.z),old=texture2D(hbPreviousExposure,vec2(.5)).r,speed=target>old?hbAdapt.x:hbAdapt.y;gl_FragColor=vec4(hbAdapt.w<.5?target:mix(old,target,1.0-exp(-speed*hbAdapt.z)),0,0,1);}`;
